// IW8 Radiant Suite entity definitions for MW2019 Replay 1.20: the equivalent of CoD Radiant's
// entities.def. Each class has a description, a box (point classes), an editor colour, whether the
// build accepts it, and its documented keys. The data is data/iw8_entity_defs.json, generated by
// tools/gen_iw8_entity_defs.py. The file is read-only at runtime.
#pragma once

#include <array>
#include <map>
#include <string>
#include <vector>

#include "geometry.h"
#include "map_text.h"

namespace iw8r {

struct KeyDef {
    std::string name, type, defaultValue, description;
    bool required = false;
    std::vector<std::string> examples;
};

struct ClassDef {
    std::string name, description, kind;  // kind: "point" or "brush"
    AABB box;                             // point classes only; invalid for brush classes
    std::array<double, 3> color{0.8, 0.8, 0.8};
    bool buildAccepted = false;           // false: the converter drops the class (compile_iw8.cpp)
    std::vector<KeyDef> keys;

    const KeyDef* key(const std::string& keyName) const;
};

class EntityDefs {
public:
    // Loads the JSON file. Returns false and sets `err` on a read or format error.
    bool load(const std::string& jsonPath, std::string* err);
    const ClassDef* find(const std::string& classname) const;
    std::vector<std::string> classNames() const;  // sorted
    // Validation for Check Map and the inspector. Returns one message per problem: missing required
    // keys, values that do not parse as the key's type, and classes the build drops.
    std::vector<std::string> validate(const Entity& e) const;

private:
    std::map<std::string, ClassDef> classes_;
};

}  // namespace iw8r
